#[test]
fn gtk_textbuffer_signals() {
    on_gtk(|| {
        let h = Harness::new();
        let s = subject_gtk_textbuffer(&h);
        h.listen(s, "begin-user-action", true).unwrap_or_else(|e| panic!("begin-user-action: {e}"));
        h.listen(s, "begin-user-action", false).unwrap();
        h.listen(s, "changed", true).unwrap_or_else(|e| panic!("changed: {e}"));
        h.listen(s, "changed", false).unwrap();
        h.listen(s, "end-user-action", true).unwrap_or_else(|e| panic!("end-user-action: {e}"));
        h.listen(s, "end-user-action", false).unwrap();
        h.listen(s, "mark-deleted", true).unwrap_or_else(|e| panic!("mark-deleted: {e}"));
        h.listen(s, "mark-deleted", false).unwrap();
        h.listen(s, "modified-changed", true).unwrap_or_else(|e| panic!("modified-changed: {e}"));
        h.listen(s, "modified-changed", false).unwrap();
        h.listen(s, "paste-done", true).unwrap_or_else(|e| panic!("paste-done: {e}"));
        h.listen(s, "paste-done", false).unwrap();
        h.listen(s, "redo", true).unwrap_or_else(|e| panic!("redo: {e}"));
        h.listen(s, "redo", false).unwrap();
        h.listen(s, "undo", true).unwrap_or_else(|e| panic!("undo: {e}"));
        h.listen(s, "undo", false).unwrap();
    });
}

#[test]
fn gtk_textbuffer_lifetime() {
    on_gtk(|| {
        let h = Harness::new();
        let s = subject_gtk_textbuffer(&h);
        let weak = h.obj(s).downgrade();
        let live = h.backend.live_handles();
        pump(30);
        assert!(weak.upgrade().is_some(), "SHARED keeps the object alive");
        h.destroy(s);
        pump(60);
        assert!(h.handle_info(s).is_err(), "released: stale");
        h.destroy(s);
        assert!(h.backend.live_handles() < live, "nothing else leaked a handle");
    });
}

